/* From Uiverse.io by vinodjangid07 - Tags: notification, card, popup */
.__UIV_SCOPE__ .notificationCard {
  width: 220px;
  height: 280px;
  background: rgb(245, 245, 245);
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 20px 35px;
  gap: 10px;
  box-shadow: 5px 5px 10px rgba(0, 0, 0, 0.123);
  border-radius: 20px;
}

.__UIV_SCOPE__ .bellIcon {
  width: 50px;
  margin: 20px 0px;
}

.__UIV_SCOPE__ .bellIcon path {
  fill: rgb(168, 131, 255);
}

.__UIV_SCOPE__ .notificationHeading {
  color: black;
  font-weight: 600;
  font-size: 0.8em;
}

.__UIV_SCOPE__ .notificationPara {
  color: rgb(133, 133, 133);
  font-size: 0.6em;
  font-weight: 600;
  text-align: center;
}

.__UIV_SCOPE__ .buttonContainer {
  display: flex;
  flex-direction: column;
  gap: 5px;
}

.__UIV_SCOPE__ .AllowBtn {
  width: 120px;
  height: 25px;
  background-color: rgb(168, 131, 255);
  color: white;
  border: none;
  border-radius: 20px;
  font-size: 0.7em;
  font-weight: 600;
  cursor: pointer;
}

.__UIV_SCOPE__ .NotnowBtn {
  width: 120px;
  height: 25px;
  color: rgb(168, 131, 255);
  border: none;
  background-color: transparent;
  font-weight: 600;
  font-size: 0.7em;
  cursor: pointer;
  border-radius: 20px;
}

.__UIV_SCOPE__ .NotnowBtn:hover {
  background-color: rgb(239, 227, 255);
}

.__UIV_SCOPE__ .AllowBtn:hover {
  background-color: rgb(153, 110, 255);
}
